import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.sendError(401, "Missing session token");
            return;
        }

        // Validate session exists (simplified)
        if (!validateSession(sessionToken)) {
            resp.sendError(403, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Whitelist report types
        if (!reportType.matches("(sales|inventory|users|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation - basic format check
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        try {
            String csvData = generateReport(reportType, startDate, endDate, customFilter);
            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", "attachment; filename=report_" + reportType + ".csv");
            resp.getWriter().write(csvData);
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String generateReport(String reportType, String startDate, String endDate, String customFilter)
            throws SQLException {
        Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
        StringBuilder csv = new StringBuilder();

        // Base query uses parameterized dates
        String baseQuery = "SELECT * FROM " + reportType + "_report_view "
                + "WHERE created_at BETWEEN ? AND ? ";

        // Custom filter is appended directly for flexible reporting
        // Note: reportType is already whitelisted above
        if (customFilter != null && !customFilter.isEmpty()) {
            baseQuery += "AND " + customFilter;
        }

        log.info("Executing report query for type: " + reportType);

        PreparedStatement stmt = conn.prepareStatement(baseQuery);
        stmt.setString(1, startDate);
        stmt.setString(2, endDate);

        ResultSet rs = stmt.executeQuery();
        ResultSetMetaData meta = rs.getMetaData();
        int colCount = meta.getColumnCount();

        // Header row
        for (int i = 1; i <= colCount; i++) {
            csv.append(meta.getColumnName(i));
            if (i < colCount) csv.append(",");
        }
        csv.append("\n");

        // Data rows
        while (rs.next()) {
            for (int i = 1; i <= colCount; i++) {
                String val = rs.getString(i);
                csv.append(val != null ? val.replace(",", ";") : "");
                if (i < colCount) csv.append(",");
            }
            csv.append("\n");
        }

        rs.close();
        stmt.close();
        conn.close();
        return csv.toString();
    }

    private boolean validateSession(String token) {
        // In production, validates against session store
        return token.length() == 64 && token.matches("[a-f0-9]+");
    }
}
